import{_ as l,C as r,o as n,c as s,j as i,E as o,a as e,a2 as d}from"./chunks/framework.C21TwvGF.js";const b=JSON.parse('{"title":"3-hafta","description":"","frontmatter":{"title":"3-hafta","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"hafta","hafta":{"sinf":{"name":"10-sinf (UX/UI)","link":"/10-sinf-uxui/"},"n":3,"bob":"III-bob · UI dizayn elementlari va vizual ierarxiya","lessons":[{"g":7,"title":"7-dars: Ranglar psixologiyasi va tipografiya","lead":"Ranglar psixologiyasi va tipografiya","link":"/10-sinf-uxui/hafta-03/dars-1","slide":"/slaydlar/10-sinf-uxui/hafta-03/dars-1.html","test":"/slaydlar/10-sinf-uxui/hafta-03/dars-1-test.html"},{"g":8,"title":"8-dars: Grid tizimlari va kompozitsiya","lead":"Grid tizimlari va kompozitsiya","link":"/10-sinf-uxui/hafta-03/dars-2","slide":"/slaydlar/10-sinf-uxui/hafta-03/dars-2.html","test":"/slaydlar/10-sinf-uxui/hafta-03/dars-2-test.html"},{"g":9,"title":"9-dars: Ikonka, tugma va navigatsiya elementlarini dizayni (UI Kit)","lead":"Ikonka, tugma va navigatsiya elementlarini dizayni (UI Kit)","link":"/10-sinf-uxui/hafta-03/dars-3","slide":"/slaydlar/10-sinf-uxui/hafta-03/dars-3.html","test":"/slaydlar/10-sinf-uxui/hafta-03/dars-3-test.html"}],"test":"/slaydlar/10-sinf-uxui/hafta-03/hafta-test.html"}},"headers":[],"relativePath":"10-sinf-uxui/hafta-03/index.md","filePath":"10-sinf-uxui/hafta-03/index.md"}'),u={name:"10-sinf-uxui/hafta-03/index.md"},g={class:"blk"},h={id:"uyga-vazifa",tabindex:"-1"};function m(y,a,f,k,v,c){const t=r("Icon");return n(),s("div",null,[i("div",g,[i("h2",h,[o(t,{name:"house"}),a[0]||(a[0]=e(" Uyga vazifa ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#uyga-vazifa","aria-label":'Permalink to "<Icon name="house" /> Uyga vazifa"'},"​",-1))]),a[2]||(a[2]=d('<p>Mazkur haftada o&#39;tilgan darslar bo&#39;yicha mustaqil bajarish uchun topshiriqlar. Har bir vazifa 20–30 daqiqaga mo&#39;ljallangan.</p><hr><h3 id="_7-dars-ranglar-psixologiyasi-va-tipografiya" tabindex="-1">7-dars: Ranglar psixologiyasi va tipografiya <a class="header-anchor" href="#_7-dars-ranglar-psixologiyasi-va-tipografiya" aria-label="Permalink to &quot;7-dars: Ranglar psixologiyasi va tipografiya&quot;">​</a></h3><ol><li>O&#39;zingiz tanlagan bitta veb-sayt yoki mobil ilova loyihasi uchun <strong>60-30-10 qoidasi</strong> bo&#39;yicha ranglar palitrasini tuzing: <ul><li>60% — Asosiy fon rangi;</li><li>30% — Ikkilamchi strukturaviy rang (kartochkalar, matn, menyu);</li><li>10% — Aksent rang (harakatga chaqiruvchi tugmalar va diqqatni tortuvchi elementlar).</li></ul></li><li>Tanlagan aksent rang va uning ustidagi matn kontrasti <strong>WCAG AA (kamida 4.5 : 1)</strong> talabiga to&#39;liq javob berishini kontrast tekshiruvchi vosita (masalan, WebAIM Contrast Checker) orqali tekshirib, natijasini yozing.</li><li>Shrift o&#39;lchamlari uchun <strong>Modular Scale (1.250 — Major Third)</strong> asosida o&#39;lchamlar ierarxiyasini tuzing: Body (16px), Subtitle (20px), H3 (25px), H2 (31px), H1 (39px).</li></ol><hr><h3 id="_8-dars-grid-tizimlari-va-kompozitsiya" tabindex="-1">8-dars: Grid tizimlari va kompozitsiya <a class="header-anchor" href="#_8-dars-grid-tizimlari-va-kompozitsiya" aria-label="Permalink to &quot;8-dars: Grid tizimlari va kompozitsiya&quot;">​</a></h3><ol><li>Desktop ekran (12 ustunli grid) uchun quyidagi sahifa strukturasini loyihalang va har bir blok necha ustun egallashini yozing: <ul><li>Chap tomondagi doimiy navigatsiya paneli (sidebar);</li><li>O&#39;rtadagi asosiy kontent va maqolalar bloki;</li><li>O&#39;ng tomondagi tezkor bildirishnomalar va tavsiyalar bloki.</li></ul></li><li>Sanoat standarti bo&#39;lgan <strong>8pt spacing (panjara) tizimi</strong>dan foydalanib, bitta mahsulot kartochkasi ichidagi barcha masofalarni (ichki padding, rasm va sarlavha orasi, matn va tugma orasi) faqat 8 ga karrali (4, 8, 16, 24, 32px) o&#39;lchamlarda belgilang.</li><li>12 ustunli desktop grididan 4 ustunli mobil gridga o&#39;tganda kartochkalar qanday qayta joylashishini 2-3 jumlada tushuntiring.</li></ol><hr><h3 id="_9-dars-ikonka-tugma-va-navigatsiya-elementlarini-dizayni-ui-kit" tabindex="-1">9-dars: Ikonka, tugma va navigatsiya elementlarini dizayni (UI Kit) <a class="header-anchor" href="#_9-dars-ikonka-tugma-va-navigatsiya-elementlarini-dizayni-ui-kit" aria-label="Permalink to &quot;9-dars: Ikonka, tugma va navigatsiya elementlarini dizayni (UI Kit)&quot;">​</a></h3><ol><li>Figma dasturida <strong>Auto Layout (<code>Shift + A</code>)</strong> yordamida bitta Primary va bitta Secondary tugma yarating: <ul><li>Matn: Inter / Roboto, 16px, Semibold;</li><li>Ichki padding: Horizontal — 24px, Vertical — 12px;</li><li>Burchak radiusi: 8px;</li><li>Minimal balandlik kamida 44px bo&#39;lishini ta&#39;minlang.</li></ul></li><li>Yaratingan Primary tugma uchun 5 ta holatni (Enabled, Hover, Focus, Active, Disabled) loyihalashtiring va ularni bitta Component Set (Variants) sifatida birlashtiring.</li><li>Yangi mobil ilova uchun 4 ta universal navigatsiya piktogrammasini (Bosh sahifa, Qidiruv, Xabarlar, Profil) 24×24px freymlar ichida tartibga keltiring.</li></ol><hr>',11))])])}const x=l(u,[["render",m]]);export{b as __pageData,x as default};
